import { markdownToDocx } from "docx.js";
export default markdownToDocx({
  inputPath: "notes/大纲.md",
  outputPath: "大纲.docx",
  title: "可选",
  defaultStyle: { font: "宋体", sizePt: 12 },
  headingStyles: { "1": { sizePt: 22, bold: true } }
});

import { buildDocx } from "docx-build.js";
export default buildDocx({ title: "报告", defaultStyle: { font: "宋体", sizePt: 12 } }, (b) => {
  b.h1("摘要").p("正文段落。").bullet("要点一");
}, "out/report.docx");

import { readDocx } from "docx.js";
const doc = readDocx("in/sample.docx");
const view = doc.textView();
const found = doc.grep("ABCD");
doc.replaceInBlock(found.matches[0].blockIndex, "ABCD", "EFGH");
doc.setBlockStyle(found.matches[0].blockIndex, { font: "宋体", sizePt: 14, bold: true });
export default { view: view.length, saved: doc.save("out/sample-edited.docx") };

import { unpackDocx, packDocx, validateDocx } from "docx-raw.js";
import fs from "fs";
const unpacked = unpackDocx("in/sample.docx", { workDir: "tmp/ooxml" });
const xmlPath = unpacked.dir + "/word/document.xml";
let xml = fs.readFileSync(xmlPath).toString();
xml = xml.replace("ABCD", "NEW");
fs.writeFileSync(xmlPath, xml);
const v = validateDocx({ dir: unpacked.dir });
if (!v.ok) throw new Error("validateDocx failed");
export default packDocx(unpacked.dir, "out/raw-edited.docx");

import { renderPptx } from "pptx.js";
export default renderPptx({
  title: "季度复盘",
  theme: "briefing",
  slides: [
    { layout: "title", title: "季度复盘", subtitle: "2026 Q3" },
    { layout: "bullets", title: "结论", items: ["收入 +12%"] },
    { layout: "shapes", shapes: [{ preset: "roundRect", col: 0, row: 0, colSpan: 6, rowSpan: 3, fill: "accent", text: "重点" }] }
  ]
}, "out/q3.pptx");

import { buildPptx } from "pptx-build.js";
export default buildPptx({ title: "演示", theme: "dark" }, (b) => {
  b.title("演示", "副标题").steps("流程", ["发现", "修复", "上线"]);
}, "out/deck.pptx");
